PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS accounts (id TEXT PRIMARY KEY, provider TEXT NOT NULL CHECK(provider IN ('gmail','microsoft')), email TEXT NOT NULL UNIQUE, display_name TEXT, daily_limit INTEGER NOT NULL DEFAULT 50, hourly_limit INTEGER NOT NULL DEFAULT 15, sent_today INTEGER NOT NULL DEFAULT 0, health TEXT NOT NULL DEFAULT 'unknown', last_health_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_states (state TEXT PRIMARY KEY, provider TEXT NOT NULL, verifier TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS leads (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, first_name TEXT, last_name TEXT, company TEXT, title TEXT, website TEXT, list_name TEXT NOT NULL DEFAULT 'Unassigned', custom_fields TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'active', source TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suppressions (email TEXT PRIMARY KEY COLLATE NOCASE, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS templates (id TEXT PRIMARY KEY, name TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', mode TEXT NOT NULL DEFAULT 'draft' CHECK(mode IN ('draft','autonomous')), approved_at TEXT, template_id TEXT, schedule_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(template_id) REFERENCES templates(id));
CREATE TABLE IF NOT EXISTS campaign_leads (campaign_id TEXT NOT NULL, lead_id TEXT NOT NULL, account_id TEXT, state TEXT NOT NULL DEFAULT 'pending', last_reply_at TEXT, PRIMARY KEY(campaign_id, lead_id), FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE, FOREIGN KEY(lead_id) REFERENCES leads(id) ON DELETE CASCADE, FOREIGN KEY(account_id) REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS sequence_steps (id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL, position INTEGER NOT NULL, delay_minutes INTEGER NOT NULL DEFAULT 0, template_id TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, UNIQUE(campaign_id, position), FOREIGN KEY(campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE, FOREIGN KEY(template_id) REFERENCES templates(id));
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', run_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 3, idempotency_key TEXT NOT NULL UNIQUE, payload TEXT NOT NULL, result TEXT, error TEXT, locked_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS jobs_due ON jobs(state, run_at);
CREATE TABLE IF NOT EXISTS send_logs (id TEXT PRIMARY KEY, job_id TEXT NOT NULL UNIQUE, campaign_id TEXT, lead_id TEXT, account_id TEXT, provider_message_id TEXT, status TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL, FOREIGN KEY(job_id) REFERENCES jobs(id));
CREATE TABLE IF NOT EXISTS agent_runs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', model TEXT NOT NULL, input_json TEXT NOT NULL, output_json TEXT, error TEXT, timeout_seconds INTEGER NOT NULL DEFAULT 90, created_at TEXT NOT NULL, finished_at TEXT);
CREATE TABLE IF NOT EXISTS knowledge (id TEXT PRIMARY KEY, category TEXT NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inbox_messages (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, provider_message_id TEXT NOT NULL, from_email TEXT, subject TEXT, received_at TEXT, intent TEXT, raw_excerpt TEXT, UNIQUE(account_id, provider_message_id));
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, level TEXT NOT NULL, event_type TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
